"use client";
import { useState } from "react";

/**
 * Share row: WhatsApp, Facebook, X, native share sheet, copy link, and a download of the
 * branded graphic (generated by /api/og from live data).
 */
export function ShareBar({ path, text, graphic, trackId, trackTable }: { path: string; text: string; graphic?: string; trackId?: string; trackTable?: "news_articles" | "memes" }) {
  const [copied, setCopied] = useState(false);
  const [open, setOpen] = useState(false);
  const url = typeof window !== "undefined" ? new URL(path, window.location.origin).toString() : path;
  const enc = encodeURIComponent;
  const track = () => {
    if (trackId && trackTable) navigator.sendBeacon?.("/api/share", JSON.stringify({ id: trackId, table: trackTable }));
  };
  const links = [
    { label: "WhatsApp", href: `https://wa.me/?text=${enc(`${text} ${url}`)}` },
    { label: "Facebook", href: `https://www.facebook.com/sharer/sharer.php?u=${enc(url)}` },
    { label: "X", href: `https://x.com/intent/post?text=${enc(text)}&url=${enc(url)}` },
  ];
  const btn = "display inline-flex items-center gap-1.5 border border-[var(--line-strong)] px-2.5 py-1 text-sm text-mist transition-colors hover:bg-chalk hover:text-ink";
  if (!open) {
    return (
      <button className={btn} onClick={() => setOpen(true)} aria-expanded={false}>
        Share ↗
      </button>
    );
  }
  return (
    <div className="flex flex-wrap items-center gap-1.5">
      {links.map((l) => (
        <a key={l.label} className={btn} href={l.href} target="_blank" rel="noopener noreferrer" onClick={track}>
          {l.label}
        </a>
      ))}
      <button
        className={btn}
        onClick={async () => {
          track();
          if (navigator.share) {
            try {
              await navigator.share({ title: "HOWAYSTATS", text, url });
              return;
            } catch {
              /* fall through to copy */
            }
          }
          await navigator.clipboard.writeText(url);
          setCopied(true);
          setTimeout(() => setCopied(false), 1800);
        }}
      >
        {copied ? "Copied" : "Copy link"}
      </button>
      {graphic && (
        <a className={`${btn} !border-chalk !text-chalk`} href={`${graphic}${graphic.includes("?") ? "&" : "?"}download=1`} download onClick={track}>
          Save image
        </a>
      )}
    </div>
  );
}
